import pandas as pd


def run(inputs: dict) -> dict:
    target_state = inputs["target_state"]
    cdc_events = inputs["cdc_events"]

    # 1. Deduplicate events by seq (at-least-once delivery -> apply once).
    events = cdc_events.drop_duplicates(subset=["seq"]).copy()

    # Build original last_seq map from target_state (for replay guard).
    orig_last_seq = {}
    state = {}
    for row in target_state.itertuples(index=False):
        oid = int(row.order_id)
        orig_last_seq[oid] = int(row.last_seq)
        state[oid] = {
            "status": row.status,
            "amount": row.amount,
            "last_seq": int(row.last_seq),
            "exists": True,
        }

    # 2. Apply replay guard based on ORIGINAL target_state last_seq.
    def guard_ok(row):
        oid = int(row.order_id)
        if oid in orig_last_seq:
            return int(row.seq) > orig_last_seq[oid]
        return True

    eligible = events[events.apply(guard_ok, axis=1)].copy()

    # 3. Sort remaining events by seq (the only trusted order).
    eligible = eligible.sort_values("seq", kind="mergesort")

    last_op_is_delete = {}
    delete_seq = {}

    for row in eligible.itertuples(index=False):
        oid = int(row.order_id)
        op = row.op
        seq = int(row.seq)

        if op in ("I", "U"):
            cur = state.get(oid)
            if cur is not None and cur.get("exists"):
                if op == "U" and pd.isna(row.amount):
                    new_amount = cur["amount"]
                else:
                    new_amount = row.amount
                state[oid] = {
                    "status": row.status,
                    "amount": new_amount,
                    "last_seq": seq,
                    "exists": True,
                }
            else:
                state[oid] = {
                    "status": row.status,
                    "amount": row.amount,
                    "last_seq": seq,
                    "exists": True,
                }
            last_op_is_delete[oid] = False
        elif op == "D":
            cur = state.get(oid)
            if cur is not None and cur.get("exists"):
                state[oid] = {
                    "status": None,
                    "amount": None,
                    "last_seq": seq,
                    "exists": False,
                }
                last_op_is_delete[oid] = True
                delete_seq[oid] = seq
            # D for missing order: no-op
        else:
            # Unknown op defensively ignored
            pass

    # 4. Build new_state from surviving rows.
    new_state_rows = []
    for oid, s in state.items():
        if s.get("exists"):
            new_state_rows.append(
                {
                    "order_id": oid,
                    "status": s["status"],
                    "amount": s["amount"],
                    "last_seq": s["last_seq"],
                }
            )

    new_state = pd.DataFrame(
        new_state_rows, columns=["order_id", "status", "amount", "last_seq"]
    )
    if len(new_state) > 0:
        new_state["order_id"] = new_state["order_id"].astype("int64")
        new_state["last_seq"] = new_state["last_seq"].astype("int64")
        new_state["amount"] = new_state["amount"].astype("float64")
        new_state["status"] = new_state["status"].astype(object)
    else:
        new_state = pd.DataFrame(
            {
                "order_id": pd.Series(dtype="int64"),
                "status": pd.Series(dtype=object),
                "amount": pd.Series(dtype="float64"),
                "last_seq": pd.Series(dtype="int64"),
            }
        )

    # 5. Build tombstones: orders whose last applied event was a 'D'.
    tomb_rows = []
    for oid, is_del in last_op_is_delete.items():
        if is_del:
            tomb_rows.append({"order_id": oid, "deleted_seq": delete_seq[oid]})

    tombstones = pd.DataFrame(tomb_rows, columns=["order_id", "deleted_seq"])
    if len(tombstones) > 0:
        tombstones["order_id"] = tombstones["order_id"].astype("int64")
        tombstones["deleted_seq"] = tombstones["deleted_seq"].astype("int64")
    else:
        tombstones = pd.DataFrame(
            {
                "order_id": pd.Series(dtype="int64"),
                "deleted_seq": pd.Series(dtype="int64"),
            }
        )

    return {"new_state": new_state, "tombstones": tombstones}
